export class MCPBus{constructor(){this.handlers=new Map();this.history=[];this.seq=0;}register(ref,handler){const k=typeof ref==='string'?ref:`${ref.kind}:${ref.id}`;this.handlers.set(k,handler);return k;}async send(message){const m=Object.freeze({id:message.id||`mcp-${++this.seq}-${Date.now()}`,at:Date.now(),...message});this.history.push(m);const target=typeof m.to==='string'?m.to:`${m.to.kind}:${m.to.id}`;const h=this.handlers.get(target);if(!h)return {ok:false,message:m,error:`Unwired target ${target}`};const out=await h(m);return {ok:true,message:m,output:out};}snapshot(){return {handlers:[...this.handlers.keys()],history:[...this.history]};}}
export default MCPBus;
